function hashStr(str){
  var h=0x811c9dc5;
  for(var i=0;i<str.length;i++){ h ^= str.charCodeAt(i); h = Math.imul(h, 0x01000193)>>>0; }
  return h>>>0;
}
function ringCreate(nodes, replicas){
  replicas=replicas||100;
  var ring={ replicas:replicas, keys:[], map:{} };
  for(var n=0;n<nodes.length;n++) ringAddNode(ring, nodes[n]);
  return ring;
}
function ringAddNode(ring, node){
  for(var i=0;i<ring.replicas;i++){
    var vh=hashStr(node + '#' + i);
    ring.map[vh]=node;
    ring.keys.push(vh);
  }
  ring.keys.sort(function(a,b){return a-b;});
  return ring;
}
function ringRemoveNode(ring, node){
  var keep=[];
  for(var i=0;i<ring.keys.length;i++){
    var key=ring.keys[i];
    if(ring.map[key]!==node) keep.push(key);
    else delete ring.map[key];
  }
  ring.keys=keep;
  return ring;
}
function ringGet(ring, key){
  var h=hashStr(key);
  var keys=ring.keys;
  var lo=0, hi=keys.length;
  while(lo<hi){ var mid=(lo+hi)>>1; if(keys[mid]<h) lo=mid+1; else hi=mid; }
  var idx = lo<keys.length ? lo : 0;
  return ring.map[keys[idx]];
}
